body:
{
  "pains": [
    {
      "id": "pain:stale-and-duplicated",
      "statement": "Half the pages in here are out of date and I only find out after I've spent two weeks building off the wrong one.",
      "element": "b2b:ease_of_doing_business:organization",
      "shape": {
        "surface": "Search returns four versions of the same doc and none of them says which one is current.",
        "operational": "Teams ship work off a superseded page, the correction arrives weeks late, and the fix is another new page that also isn't announced.",
        "personal": "You look like the person who missed the memo, in front of the people whose work you just wasted."
      },
      "workflow": "Notion search and the sidebar, at the start of a sprint or before a customer call, when someone needs the current spec and finds three candidates with no way to tell which one is live.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A teammate publishes a replacement page and never tells anyone the old one is dead", "cites": ["src:1"] },
        { "event": "Someone leaves and the pages they owned quietly stop being maintained", "cites": ["src:10", "src:11"] },
        { "event": "A new hire is onboarded off the wiki and hits the stale pages first", "cites": ["src:9", "src:10"] }
      ],
      "who_feels": ["end_user", "champion", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "The Notion spaces used by the Product and Program managers I worked with in the past few years have become a collection of half-finished documents that are always out of date, hard to find, and often superseded by some new Notion page they created but forgot to tell us about until we had spent weeks following the old one.", "cites": ["src:1"] },
            { "situation": "when_refusing", "verbatim": "I've had better success lately asking people to step outside of Notion and instead work in an old-fashioned shared Google doc.", "cites": ["src:1"] }
          ],
          "costs_them": "Weeks of work built on a spec that was replaced without notice, plus the rework once someone notices.",
          "fears": "That the page they are reading right now is also the dead one and nobody will say so.",
          "dream_outcome": "Open the page and know, without asking, that it is the current one."
        },
        "champion": {
          "says": [
            { "situation": "venting", "verbatim": "A succession of wiki products that are essentially write-only. No one ever reads them.", "cites": ["src:9"] },
            { "situation": "to_their_boss", "verbatim": "All documentation goes out of date and no single person can keep it up to date.", "cites": ["src:10"] },
            { "situation": "when_it_bites", "verbatim": "It seems that people consider creating and updating documentation someone else's job.", "cites": ["src:10"] }
          ],
          "costs_them": "Tidying becomes a standing second job nobody assigned them and nobody counts.",
          "fears": "Being the only person who cares, until they stop caring and the whole thing rots.",
          "dream_outcome": "Upkeep happens as a side effect of people doing their work, not as a separate chore."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_comparing", "verbatim": "Eventually somebody gets frustrated with the disorganization and says \"We should switch to Yet Another Wiki Product\" and the cycle begins anew.", "cites": ["src:9"] }
          ],
          "costs_them": "A migration every few years that resets the knowledge base instead of fixing it.",
          "fears": "Paying for the fourth wiki and getting the same mess with a new logo.",
          "dream_outcome": "The workspace stays trustworthy without another migration."
        }
      },
      "segments": ["seg:startup", "seg:enterprise"],
      "feature_ref": "feat:ai",
      "cites": ["src:1", "src:9", "src:10", "src:11"]
    },
    {
      "id": "pain:cant-find-what-we-wrote",
      "statement": "I know we wrote this down somewhere, I just can't find it, so I go interrupt whoever wrote it.",
      "element": "b2b:ease_of_doing_business:information",
      "shape": {
        "surface": "Search doesn't surface it, and the answer turns out to be three levels deep in a page nobody linked.",
        "operational": "The question gets re-answered in chat, and that answer never makes it back into the workspace, so the next person asks again.",
        "personal": "You burn an afternoon and pull two other people off their work to learn something the company already knew."
      },
      "workflow": "Notion search first, then the sidebar, then Drive and Slack, then giving up and pinging the one person who remembers - usually mid-task, when a customer or a teammate is waiting on you.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A new hire asks a question the wiki is supposed to answer", "cites": ["src:10", "src:21"] },
        { "event": "The person who knew it is on holiday, or has left", "cites": ["src:10", "src:11"] },
        { "event": "Search returns nothing useful on the first try", "cites": ["src:21"] }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "information would become inaccessible from time to time, to the point it was pretty much useless", "cites": ["src:11"] }
          ],
          "costs_them": "Hours a week of looking, and the interruptions they hand to everyone else.",
          "fears": "Redoing work that already exists and having someone point that out in review.",
          "dream_outcome": "Ask in plain language, get the answer with the page it came from, first try."
        },
        "champion": {
          "says": [
            { "situation": "venting", "verbatim": "Search is limited to a single platform or system, and does not always work well.", "cites": ["src:10"] }
          ],
          "costs_them": "They become the human search index for their team.",
          "fears": "That the knowledge base is judged useless and everyone quietly goes back to asking in chat.",
          "dream_outcome": "People find it themselves and stop asking them."
        }
      },
      "segments": ["seg:startup", "seg:enterprise", "seg:individual"],
      "feature_ref": "feat:kb",
      "cites": ["src:10", "src:11", "src:21"]
    },
    {
      "id": "pain:too-slow-to-catch-a-thought",
      "statement": "It is slow enough to open that I've started deciding the thought wasn't worth writing down.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "Ten seconds to open a page, lag while typing, a mobile app that takes ten seconds to launch, tabs eating CPU in the background.",
        "operational": "The notes that were supposed to land never land, so the workspace is missing exactly the things people didn't have a spare minute to type.",
        "personal": "The tool trains you out of using it, and you feel the small defeat every time you decide not to bother."
      },
      "workflow": "The desktop app in the ninety seconds between meetings, and the phone app in a hallway - the only two windows where capture actually happens.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Trying to jot an idea down between meetings", "cites": ["src:2"] },
        { "event": "Opening the mobile app to check one thing", "cites": ["src:4"] },
        { "event": "Keeping a working set of tabs open through the day", "cites": ["src:5", "src:3"] },
        { "event": "A database grows past a few hundred rows", "cites": ["src:8"] }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "a lot of opportunities to jot an idea down, or file something in the right place, were lost because of that slight lag", "cites": ["src:2"] },
            { "situation": "venting", "verbatim": "Opening a note in a tab take 10 seconds and interrupts me half the time with some random news or a prompt to try some AI feature.", "cites": ["src:3"] },
            { "situation": "when_comparing", "verbatim": "Meanwhile their mobile app was taking literally 10+ seconds to even open.", "cites": ["src:4"] },
            { "situation": "when_refusing", "verbatim": "Notion was unusable after more than a few hundred items in a DB.", "cites": ["src:8"] }
          ],
          "costs_them": "Ideas and filing that never happen, plus a laptop they have to babysit.",
          "fears": "That the thing they didn't write down was the one that mattered.",
          "dream_outcome": "Opening it is never a decision - it is there before they finish reaching for it."
        }
      },
      "segments": ["seg:individual", "seg:startup", "seg:enterprise"],
      "feature_ref": null,
      "feature_note": "Nothing in brain/company answers speed; every feature listed adds surface. What kills this is load and typing latency low enough that opening the app is never weighed against the value of the thought.",
      "cites": ["src:2", "src:3", "src:4", "src:5", "src:8"]
    },
    {
      "id": "pain:gone-when-the-network-is",
      "statement": "If the connection drops I can't work, and one time it silently took a page I'd already written.",
      "element": "b2b:ease_of_doing_business:availability",
      "shape": {
        "surface": "Plane, train, bad hotel wifi, vendor outage: the workspace is a blank screen.",
        "operational": "Work stops, or worse, edits fail to save with no warning and nobody notices until the page is short.",
        "personal": "You stop trusting it with anything you can't afford to lose, so the important writing quietly moves somewhere else."
      },
      "workflow": "Writing in Notion on a flight or during an outage, and the save state you cannot see because there isn't one to look at.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Travel with no reliable connection, without having pre-selected pages", "cites": ["src:6"] },
        { "event": "A Notion outage while mid-edit", "cites": ["src:23"] }
      ],
      "who_feels": ["end_user", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_refusing", "verbatim": "An offline mode that requires me to individually download the pages and database rows I'm expecting to need beforehand is not the kind of \"offline mode\" that meets my needs.", "cites": ["src:6"] }
          ],
          "costs_them": "Dead time whenever they are off a good connection, and re-typing anything that was lost.",
          "fears": "Losing work they can't prove they wrote.",
          "dream_outcome": "It just works offline, with no decision made in advance about what they'll need."
        },
        "technical_evaluator": {
          "says": [
            { "situation": "when_comparing", "verbatim": "with Notion I've actually lost data, sometimes a lot of it. (Once when Notion was having some kind of outage, I silently lost an entire page I was working on.)", "cites": ["src:23"] },
            { "situation": "when_refusing", "verbatim": "Not silently losing data is a low bar to clear for an application that edits rich text. Notion didn't clear it.", "cites": ["src:23"] }
          ],
          "costs_them": "They have to answer for the tool they approved when someone loses a page.",
          "fears": "A data-loss incident with no local copy to recover from.",
          "dream_outcome": "Edits that survive the network, provably, without anyone thinking about it."
        }
      },
      "segments": ["seg:individual", "seg:startup", "seg:enterprise"],
      "feature_ref": null,
      "feature_note": "Offline is not in the brain/company feature list. Notion shipped an offline mode in August 2025; src:6 is a complaint about its shape - pre-selecting pages to download - not about its absence, so the gap is now scope, not existence.",
      "cites": ["src:6", "src:23"]
    },
    {
      "id": "pain:paying-more-for-ai-i-dont-trust",
      "statement": "We moved up a tier for the AI and it hands me generic slop, and it can't see the data I actually keep in here.",
      "element": "b2b:table_stakes:acceptable_price",
      "shape": {
        "surface": "You ask it for something specific, get a confident generic answer, and go do it yourself.",
        "operational": "The AI tier is bought for every seat and used by a handful of people, while the features that used to be included move up the price list.",
        "personal": "You championed the upgrade, and now you are the one defending the line item."
      },
      "workflow": "The Ask AI box on a page mid-task, and then the renewal conversation where somebody asks what the higher tier actually bought.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "First real attempt to get the AI to do a specific piece of work", "cites": ["src:17"] },
        { "event": "Asking it about data that lives in a database", "cites": ["src:16"] },
        { "event": "A feature they were using moves behind a higher tier", "cites": ["src:20"] }
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_refusing", "verbatim": "Just tried Notion AI to build me a mermaid diagram and it was totally useless. So probably not bothering with that again. I can write good enough English without it and I don't want to sound like generic slop anyway.", "cites": ["src:17"] },
            { "situation": "when_it_bites", "verbatim": "It's just too bad Notion AI can't see data stored in databases, which is arguably Notions biggest value add and differentiator.", "cites": ["src:16"] }
          ],
          "costs_them": "Time spent prompting something that was never going to answer, then doing it by hand anyway.",
          "fears": "Shipping something the AI wrote that reads like slop and having their name on it.",
          "dream_outcome": "Ask it about their own data and get an answer good enough to act on without checking."
        },
        "economic_buyer": {
          "says": [
            { "situation": "venting", "verbatim": "I find incredibly disappointing that so many new features have been walled behind higher tiers. Notion forgot that we pay monthly price so that they can keep developing their software to our benefit too", "cites": ["src:20"] }
          ],
          "costs_them": "A per-seat bill that rises faster than the number of people who use what it bought.",
          "fears": "Being asked at renewal to show what the AI tier returned, and having nothing to show.",
          "dream_outcome": "The higher tier pays for itself in work people can point at."
        }
      },
      "segments": ["seg:individual", "seg:startup", "seg:enterprise"],
      "feature_ref": "feat:ai",
      "cites": ["src:16", "src:17", "src:20"]
    },
    {
      "id": "pain:every-ai-feature-is-a-new-security-review",
      "statement": "Every AI feature they ship is another thing I have to get past security, and their handling of the last one doesn't help me make the case.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "A published exfiltration write-up, a disclosure closed as Not Applicable, and an internal thread asking whether agents should be switched off.",
        "operational": "The rollout stalls while someone writes a risk memo, and AI features get disabled workspace-wide in the meantime.",
        "personal": "You vouched for this tool internally. If company data walks out through it, that is your name on the approval."
      },
      "workflow": "The security review before enabling Notion AI or agents for the workspace, and the follow-up question nobody can answer cleanly: what exactly can an agent reach, and who can see that it did.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "A public report of data exfiltration through the AI features", "cites": ["src:19"] },
        { "event": "A responsible disclosure closed without action", "cites": ["src:19", "src:18"] }
      ],
      "who_feels": ["blocker", "technical_evaluator"],
      "by_role": {
        "blocker": {
          "says": [
            { "situation": "when_refusing", "verbatim": "As much as I love using Notion, they have a terrible track record when it comes to dealing with and responding to security issues.", "cites": ["src:18"] }
          ],
          "costs_them": "They carry the residual risk of a tool the whole company already lives in.",
          "fears": "An incident traced back to a feature they signed off on.",
          "dream_outcome": "A per-agent permission and audit trail they can read and sign without a research project."
        },
        "technical_evaluator": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "> We responsibly disclosed this vulnerability to Notion via HackerOne. Unfortunately, they said \"we're closing this finding as `Not Applicable`\".", "cites": ["src:19"] }
          ],
          "costs_them": "Evaluation time spent chasing vendor responses instead of testing the product.",
          "fears": "That the next issue is also dismissed and they only hear about it from a blog post.",
          "dream_outcome": "A vendor whose disclosure record is an argument for the tool, not against it."
        }
      },
      "segments": ["seg:startup", "seg:enterprise"],
      "feature_ref": null,
      "feature_note": "Nothing in brain/company speaks to admin controls, audit, or the blast radius of an agent. What kills this is a readable permission and audit surface for agents, plus a disclosure record a reviewer can cite.",
      "cites": ["src:18", "src:19"]
    },
    {
      "id": "pain:easier-to-put-in-than-take-out",
      "statement": "Getting content out is far harder than getting it in, which makes me nervous about how much of us now lives in there.",
      "element": "b2b:ease_of_doing_business:flexibility",
      "shape": {
        "surface": "Export to markdown, edit, reimport, and half the formatting is gone; the native format behind the API is complex JSON.",
        "operational": "There is no credible exit plan, so the migration that gets discussed every year never actually gets scoped, and access disputes leave the data on the vendor's side.",
        "personal": "You are the person who put the company's knowledge into a box you cannot open."
      },
      "workflow": "The export button and the API, usually during the annual 'should we still be on this' conversation, or the week somebody tries to round-trip a page through a text editor.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "Trying a round-trip export and reimport and losing formatting", "cites": ["src:7"] },
        { "event": "A billing or account dispute that cuts off access to company data", "cites": ["src:22"] },
        { "event": "Evaluating a move to another tool", "cites": ["src:8"] }
      ],
      "who_feels": ["technical_evaluator", "economic_buyer", "end_user"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "They claim you can export stuff as markdown, but if I export as markdown, edit and reimport, I lose half of the formatting – even basic formatting which is part of the markdown spec.", "cites": ["src:7"] },
            { "situation": "when_comparing", "verbatim": "Their native format (which their API exposes) is a bunch of extremely complex JSON blobs. I thought about writing a tool to let me download stuff, edit it in a sane text editor, then reupload it, but when I saw the complexity I just gave up.", "cites": ["src:7"] }
          ],
          "costs_them": "Any tooling they want to build around the workspace costs more than it should, or gets abandoned.",
          "fears": "Being told to migrate and discovering it cannot be done cleanly.",
          "dream_outcome": "A round trip out and back that loses nothing."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Ask HN: Notion is withholding my company data, what can I do?", "cites": ["src:22"] }
          ],
          "costs_them": "Negotiating leverage: they cannot credibly threaten to leave.",
          "fears": "The company's operating knowledge held hostage by an account problem.",
          "dream_outcome": "A standing export they control, so staying is a choice."
        },
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "I use Notion because I have to, not because I like it.", "cites": ["src:7"] },
            { "situation": "when_refusing", "verbatim": "I just migrated everything out of Notion into Ibsidian.", "cites": ["src:8"] }
          ],
          "costs_them": "They keep a parallel copy of anything they care about.",
          "fears": "Their own notes trapped in someone else's format.",
          "dream_outcome": "Their content in plain files they can read without the app."
        }
      },
      "segments": ["seg:individual", "seg:startup", "seg:enterprise"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company covers export or portability. What kills this is a lossless round trip to plain files and an export the customer can run on their own schedule.",
      "cites": ["src:7", "src:8", "src:22"]
    },
    {
      "id": "pain:decisions-live-in-calls-not-pages",
      "statement": "We decide things on calls and in Slack, and unless somebody writes it up we decide the same thing again three weeks later.",
      "element": "b2b:ease_of_doing_business:reduced_effort",
      "shape": {
        "surface": "The page that should hold the decision is empty or stale, and the real answer is buried in a thread or a recording.",
        "operational": "Writing it up is an extra step bolted onto the end of a meeting, so it is the first thing dropped when the day is full.",
        "personal": "The write-up is unpaid work that only ever gets noticed when it is missing."
      },
      "workflow": "The ten minutes after a call, when somebody is supposed to turn the conversation into a page and instead joins the next call.",
      "type": "latent",
      "confidence": "medium",
      "revealed_by": "feat:meeting",
      "triggers": [
        { "event": "A decision reached in a meeting with no named owner for the write-up", "cites": ["src:11"] },
        { "event": "A good answer given in Slack or a PR review that never reaches the wiki", "cites": ["src:10"] }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "knowledge sharing/maintenance was simply being an extra step in our work, a mostly disregarded one, almost an after thought", "cites": ["src:11"] }
          ],
          "costs_them": "Re-arguing settled questions, and the write-up tax on every meeting they own.",
          "fears": "Being the one blamed for a decision nobody recorded.",
          "dream_outcome": "The decision is a page by the time the call ends, without them typing it."
        },
        "champion": {
          "says": [
            { "situation": "to_their_boss", "verbatim": "if you are answering a question on Slack, email, or a PR review, spend a bit more time writing a clear response, and then add it to your wiki", "cites": ["src:10"] },
            { "situation": "venting", "verbatim": "We decided that if we ever make a decision, or arrive at a conclusion, that's worth sharing, then it should be worth writing.", "cites": ["src:11"] }
          ],
          "costs_them": "Constant nudging of colleagues to do a step none of them are measured on.",
          "fears": "That the discipline dies the moment they stop pushing.",
          "dream_outcome": "Capture happens by default, and their job is curation not transcription."
        }
      },
      "segments": ["seg:startup", "seg:enterprise"],
      "feature_ref": "feat:meeting",
      "cites": ["src:10", "src:11"]
    },
    {
      "id": "pain:knowledge-scattered-across-tools",
      "statement": "Half of what I need isn't in Notion at all - it's in Slack, Drive, a GitHub README or somebody's Loom.",
      "element": "b2b:ease_of_doing_business:integration",
      "shape": {
        "surface": "You search Notion, then Drive, then Slack, then ask a person, and you still don't know if you looked everywhere.",
        "operational": "Every new tool takes a slice of the knowledge with it, and the links between the slices rot quietly.",
        "personal": "You never get the feeling of having actually finished looking."
      },
      "workflow": "The search-across-four-tools ritual before admitting defeat and asking in chat, and the moment another team standardises on Confluence or Drive instead.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Another team inside the company standardises on a different tool", "cites": ["src:7"] },
        { "event": "Adding one more tool to the stack", "cites": ["src:11"] },
        { "event": "A search that fails on the first attempt and sends them to a colleague", "cites": ["src:21"] }
      ],
      "who_feels": ["end_user", "champion", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_looking", "verbatim": "Information can live in Confluence, Notion, a wiki, Google sheets, presentations, GitHub READMEs, public Slack channels, recorded Loom videos, and the list goes on.", "cites": ["src:10"] }
          ],
          "costs_them": "The same question searched four times in four places.",
          "fears": "Acting on a partial answer because they never found the other half.",
          "dream_outcome": "One search that covers everywhere the company actually writes."
        },
        "champion": {
          "says": [
            { "situation": "when_comparing", "verbatim": "Get everthing in the same place as much as possible, with every new tool you'll loose out (knowledge bits here and there, extra connections that stop working, or that people don't bother to check)", "cites": ["src:11"] }
          ],
          "costs_them": "Fighting tool sprawl they don't have the authority to stop.",
          "fears": "The workspace becoming one silo among five rather than the place.",
          "dream_outcome": "Notion is where people look first because it reaches the other tools."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Other teams still use Confluence.", "cites": ["src:7"] }
          ],
          "costs_them": "Paying for two or three overlapping systems and getting one fragmented answer.",
          "fears": "Standardising on Notion and still ending up with Confluence next door.",
          "dream_outcome": "One consolidation that actually consolidates."
        }
      },
      "segments": ["seg:startup", "seg:enterprise"],
      "feature_ref": "feat:kb",
      "cites": ["src:7", "src:10", "src:11", "src:21"]
    },
    {
      "id": "pain:building-the-system-instead-of-using-it",
      "statement": "I spent my weekends tuning the setup and got no actual work out of it.",
      "element": "b2c:functional:simplifies",
      "shape": {
        "surface": "New databases, relations, dashboards and templates, and the to-do list is exactly as long as it was.",
        "operational": "The system needs more upkeep than the person will sustain, so it gets abandoned for Apple Notes, a folder of markdown, or paper.",
        "personal": "It feels like progress the whole time it is happening and like waste the moment you stop."
      },
      "workflow": "Evenings and weekends inside Notion's database, relation and template UI, building the container that is supposed to hold the work instead of doing the work.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Watching a Notion setup video or buying a template pack", "cites": ["src:13", "src:14"] },
